def choose_move(observation):
    def i(v, d=0):
        try:
            return int(v if v is not None else d)
        except:
            return d

    def p(v):
        if isinstance(v, dict):
            return i(v.get("x", v.get("col", 0))), i(v.get("y", v.get("row", 0)))
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return i(v[0]), i(v[1])
        return 0, 0

    def pts(v):
        out = []
        for c in v or []:
            out.append(p(c))
        return out

    def s(v):
        return set(pts(v))

    w = i(observation.get("grid_width", observation.get("width", observation.get("cols", 0))))
    h = i(observation.get("grid_height", observation.get("height", observation.get("rows", 0))))
    sx, sy = p(observation.get("self_position", observation.get("agent_position", (0, 0))))
    ox, oy = p(observation.get("opponent_position", observation.get("enemy_position", (0, 0))))

    resources = pts(observation.get("resources", observation.get("targets", [])))
    obstacles = s(observation.get("obstacles", []))
    bad = obstacles | s(observation.get("self_path", [])) | s(observation.get("opponent_path", []))

    own_terr = s(observation.get("self_territory", observation.get("owned_cells", [])))
    opp_terr = s(observation.get("opponent_territory", observation.get("enemy_cells", [])))

    dirs = [(0, 0), (0, -1), (1, 0), (0, 1), (-1, 0)]

    def ok(x, y):
        return 0 <= x < w and 0 <= y < h and (x, y) not in bad

    def md(ax, ay, bx, by):
        return abs(ax - bx) + abs(ay - by)

    def center_dist(x, y):
        if w > 0 and h > 0:
            return abs(x - (w - 1) / 2.0) + abs(y - (h - 1) / 2.0)
        return 0

