            score -= md(nx, ny, target[0], target[1]) * 12
        else:
            score += center_dist(sx, sy) - center_dist(nx, ny)

        d_opp = md(nx, ny, ox, oy)
        score += d_opp * (10 if near_opp else 3)

        if (nx, ny) in own_terr:
            score += 2
        if (nx, ny) in opp_terr:
            score -= 2

        if dx == 0 and dy == 0:
            score -= 1

        # prefer moves with more open adjacent cells
        open_adj = 0
        for ax, ay in ((0, -1), (1, 0), (0, 1), (-1, 0)):
            if ok(nx + ax, ny + ay):
                open_adj += 1
        score += open_adj

        cand = (score, -abs(dx) - abs(dy), -d_opp, dx, dy)
        if best_move is None or cand > best_move:
            best_move = cand

